import assert from 'node:assert/strict';import{fileURLToPath}from'node:url';const{chromium}=await import(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');import{writeFile}from'node:fs/promises';const b=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'}),results=[];try{const p=await b.newPage({viewport:{width:1100,height:1200}});for(const[width,height]of[[320,400],[375,500],[390,844],[440,952]])for(const scene of['figma','six']){await p.goto('http://127.0.0.1:5173/tests/fixtures/layout-audit.html?'+new URLSearchParams({layout:'original',width,height,scene,scale:110}),{waitUntil:'domcontentloaded'});await p.locator('#audit-stage[data-ready=true]').waitFor();const r=await p.locator('#audit-stage').evaluate(root=>{const rect=e=>{const r=e.getBoundingClientRect();return{x:r.x,y:r.y,w:r.width,h:r.height}};const info=rect(root.querySelector('.mx-room-info'));const cards=[...root.querySelectorAll('.mx-board .mx-public-slot,.mx-seat-mine .mx-card-slot')].filter(e=>e.checkVisibility()).map(rect);const hit=(a,b)=>Math.min(a.x+a.w,b.x+b.w)>Math.max(a.x,b.x)+.5&&Math.min(a.y+a.h,b.y+b.h)>Math.max(a.y,b.y)+.5;return{info,collisions:cards.filter(r=>hit(info,r))}});results.push({width,height,scene,...r});console.log(width,height,scene,r.collisions.length);}}finally{await b.close();await writeFile(fileURLToPath(new URL('../../docs/qa/product-2026-11-17/original-content-check.json',import.meta.url)),JSON.stringify(results,null,2));}

assert.equal(results.length,8);assert.ok(results.every(r=>r.collisions.length===0),'room information overlaps cards');
